    "analystView": "利率环境偏紧: 10Y 4.95% (近1年分位 100), 曲线熊陡 +39bp——长端上行快于短端, 通常对应增长/供给驱动而非纯货币紧缩。资产定价视角: 实际利率 (2.55%) 是成长股估值的核心折现率, 通胀预期 (2.36%) 决定名义端; 当前实际利率高位 + 分位极值, 长久期成长资产 (纳指/半导体/未盈利科技) 的估值压缩风险最高, 而短久期价值/金融板块相对受益于陡峭曲线。风险事件: 若 2Y 补涨 (曲线熊平) 说明紧缩向短端传导, 对全市场估值最不利。",
